window.docContents[117].resolve({"/Equiv/#Hoare-Logic--Equiv___-Program-Equivalence--Program-Transformation--Soundness-of-Constant-Folding":{"contents":"Now we need to show that what we've done is correct.\n\nHere's the proof for arithmetic expressions.\n\ntheorem Aexp.foldConstants_sound : TransSound Aexp.foldConstants := by\n  intro a st\n  induction a with\n  | num n | id x => rfl\n  | _ a₁ a₂ _ _ =>\n    -- `plus`, `minus`, and `mult` follow from the IH and the observation that\n    -- `(aexp {~a₁ + ~a₂}).eval st = a₁.eval st + a₂.eval st\n    --   = (Aexp.num (a₁.eval st + a₂.eval st)).eval st`\n    -- (and similarly for `minus`/`-` and `mult`/`*`).\n    cases Aexp.foldConstants_cases a₁ a₂ with\n    | inl h =>\n      obtain ⟨n₁, n₂, h₁, h₂⟩ := h\n      simp_all [foldConstants]\n    | inr h =>\n      simp_all\n\n\nAn equivalent version using the fun_induction tactic would look simpler:\n\ntheorem Aexp.foldConstants_sound' : TransSound Aexp.foldConstants := by\n  intro a st\n  fun_induction Aexp.foldConstants <;> simp_all\n\n\nHere is an informal proof of the eq case of the soundness\nargument for boolean expression constant folding.  Read it\ncarefully and compare it to the formal proof that follows.  Then\nfill in the le and gt cases of the formal proof (without looking\nat the eq case, if possible).Theorem: The constant folding function for booleans,\nBexp.foldConstants, is sound.Proof: We must show that b is equivalent to b.foldConstants,\nfor all boolean expressions b.  Proceed by induction on b.  We\nshow just the case where b has the form a₁ = a₂.In this case, we must show  (bexp { a₁ = a₂ }).eval st = (bexp { a₁ = a₂ }).foldConstants.eval st\nThere are two cases to consider.First, suppose a₁.foldConstants = aexp { n₁ } and\na₂.foldConstants = aexp { n₂ } for some n₁ and n₂.\nIn this case, we have  (bexp { a₁ = a₂ }).foldConstants = if (n₁ = n₂) then bexp { true } else bexp { false }\nand  (bexp {a₁ = a₂}).eval st = a₁.eval st = a₂.eval st.\nBy the soundness of constant folding for arithmetic\nexpressions (Aexp.foldConstants_sound), we know           a₁.eval st\n         = (a₁.foldConstants).eval st\n         = (aexp { n₁ }).eval st\n         = n₁\nand           a₂.eval st\n         = (a₂.foldConstants).eval st\n         = (aexp { n₂ }).eval st\n         = n₂\nso          (bexp { a₁ = a₂ }).eval st\n         = a₁.eval st = a₂.eval st\n         = n₁ = n₂\nAlso, it is easy to see (by considering the cases n₁ = n₂ and\nn₁ ≠ n₂ separately) that          (if n₁ = n₂ then (bexp { true }) else (bexp { false }) ).eval st\n         = if n₁ = n₂ then bexp { true }.eval st else bexp { false }.eval st\n         = if n₁ = n₂ then true else false\n         = n₁ = n₂\nSo          (bexp { a₁ = a₂ }).eval st\n         = n₁ = n₂\n         = (if n₁ = n₂ then (bexp { true }) else (bexp { false }) ).eval st,\nas required.Otherwise, one of a₁.foldConstants and a₂.foldConstants is not a\nconstant.  In this case, we must show           (bexp { a₁ = a₂ }).eval st\n         = (bexp { (a₁.foldConstants = a₂.foldConstants) }).eval st,\nwhich, by the definition of Bexp.eval, is the same as showing           a₁.eval st = a₂.eval st\n        = (a₁.foldConstants).eval st = (a₂.foldConstants).eval st\nBut the soundness of constant folding for arithmetic\nexpressions (Aexp.foldConstants_sound) gives us         a₁.eval st = (a₁.foldConstants).eval st\n         a₂.eval st = (a₂.foldConstants).eval st\ncompleting the case.theorem Bexp.foldConstants_sound : Bexp.TransSound Bexp.foldConstants := by\n  intro b st\n  induction b with\n  | bool b => cases b <;> rfl\n  | eq a₁ a₂ =>\n    have h₁ : Aexp.eval st a₁.foldConstants = Aexp.eval st a₁ :=\n      Aexp.foldConstants_sound a₁ st\n    have h₂ : Aexp.eval st a₂.foldConstants = Aexp.eval st a₂ :=\n      Aexp.foldConstants_sound a₂ st\n    cases Bexp.foldConstants_comp a₁ a₂ with\n    | inl h =>\n      -- The only interesting case: both `a₁` and `a₂` fold to constants\n      obtain ⟨n₁, n₂, hn₁, hn₂⟩ := h\n      by_cases n₁ = n₂ <;> simp_all [foldConstants]\n    | inr h =>\n      simp_all\n  | neq a₁ a₂ =>\n    have h₁ : Aexp.eval st a₁.foldConstants = Aexp.eval st a₁ :=\n      Aexp.foldConstants_sound a₁ st\n    have h₂ : Aexp.eval st a₂.foldConstants = Aexp.eval st a₂ :=\n      Aexp.foldConstants_sound a₂ st\n    cases Bexp.foldConstants_comp a₁ a₂ with\n    | inl h =>\n      obtain ⟨n₁, n₂, hn₁, hn₂⟩ := h\n      by_cases n₁ = n₂ <;> simp_all [foldConstants]\n    | inr h =>\n      simp_all\n  | le a₁ a₂ =>\n    solution!\n      have h₁ : Aexp.eval st a₁.foldConstants = Aexp.eval st a₁ :=\n      Aexp.foldConstants_sound a₁ st\n      have h₂ : Aexp.eval st a₂.foldConstants = Aexp.eval st a₂ :=\n        Aexp.foldConstants_sound a₂ st\n      cases Bexp.foldConstants_comp a₁ a₂ with\n      | inl h =>\n        obtain ⟨n₁, n₂, hn₁, hn₂⟩ := h\n        by_cases n₁ ≤ n₂ <;> simp_all [foldConstants, Nat.not_le_of_gt]\n      | inr h =>\n        simp_all\n  | gt a₁ a₂ =>\n    solution!\n      have h₁ : Aexp.eval st a₁.foldConstants = Aexp.eval st a₁ :=\n      Aexp.foldConstants_sound a₁ st\n      have h₂ : Aexp.eval st a₂.foldConstants = Aexp.eval st a₂ :=\n        Aexp.foldConstants_sound a₂ st\n      cases Bexp.foldConstants_comp a₁ a₂ with\n      | inl h =>\n        obtain ⟨n₁, n₂, hn₁, hn₂⟩ := h\n        by_cases n₁ > n₂ <;> simp_all [foldConstants, Nat.not_lt_of_le]\n      | inr h =>\n        simp_all\n  | not b ih =>\n    cases Bexp.foldConstants_unary b with\n    | inl h =>\n      rcases h with h | h <;> simp_all [foldConstants]\n    | inr h =>\n      simp_all\n  | and b₁ b₂ ih₁ ih₂ =>\n    cases Bexp.foldConstants_binary b₁ b₂ with\n    | inl h =>\n      obtain ⟨h₁ | h₁, h₂ | h₂⟩ := h <;> simp_all [foldConstants]\n    | inr h =>\n      simp_all\n\n\nComplete the while case of the following proof.theorem Com.foldConstants_sound : Com.TransSound Com.foldConstants := by\n  intro c\n  induction c with\n  | skip =>\n      simp [Com.foldConstants]\n  | asgn x a =>\n      apply Com.congruence_asgn\n      apply Aexp.foldConstants_sound\n  | seq c₁ c₂ ih₁ ih₂ =>\n      apply Com.congruence_seq <;> assumption\n  | cond b c₁ c₂ ih₁ ih₂ =>\n      simp only [Com.foldConstants]\n      have hb : b.foldConstants ≃ b := by\n        apply Bexp.foldConstants_sound\n      -- If the optimization doesn't eliminate the `if`, then the\n      -- result is easy to prove from the `ih` and\n      -- `Bexp.foldConstants_sound`\n      cases heq : b.foldConstants <;> try (apply Com.congruence_if <;> simp_all)\n      · case cond.bool b =>\n          cases b with\n          | false =>\n              apply Com.equiv_trans <;> try assumption\n              symm; apply Com.if_false; simp_all\n          | true =>\n              apply Com.equiv_trans <;> try assumption\n              symm; apply Com.if_true; simp_all\n  | whileDo b c ih =>\n      solution!\n        simp only [Com.foldConstants]\n        have hb : b.foldConstants ≃ b := by\n          apply Bexp.foldConstants_sound\n        -- Again, the cases where `Com.foldConstants` doesn't change the test\n        -- or don't change the loop body follow from the `ih` and\n        -- `Bexp.foldConstants_sound`\n        cases heq : b.foldConstants <;> try (apply Com.congruence_while <;> simp_all)\n        · case whileDo.bool b =>\n          cases b with\n          | false =>\n              symm; apply Com.while_false; simp_all\n          | true =>\n              symm; apply Com.while_true; simp_all\n\n\n","context":"Hoare Logic\u0009Equiv: Program Equivalence\u0009Program Transformation","header":"4.3.2. Soundness of Constant Folding","id":"/Equiv/#Hoare-Logic--Equiv___-Program-Equivalence--Program-Transformation--Soundness-of-Constant-Folding"}});